        }
      ],
      "key": "occurrence_profile",
      "label": "Traversal occurrence profile"
    },
    {
      "conditions": [],
      "definition": "Closed constraint kinds: identity_dependency_acyclic, occurrence_causation_acyclic, event_causation_acyclic, occurrence_seed_complete, relation_claim_admissible, semantic_cut_complete, pre_effect_current, operation_grant_contains_effect, event_scope_compatible, frontier_complete, transition_subject_complete. Closed judgment kinds: model_validation, occurrence_admission, event_admission, claim_admission, semantic_cut_admission, effect_readiness, transition_evaluation, frontier_projection. Closed residual kinds: unobserved_subject_state, partial_effect, unresolved_cause, unresolved_scope, competing_lineage, stale_frontier, stale_currentness, unobserved_external_mutation. Closed stop kinds: hold, gap, refusal, invalid_basis, out_of_scope, partial_effect. Sigma_occurrence.FunctorKind contains only exact b_ac references to F_D, F_P and F_H, without changing their laws.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 714,
          "quote": "identity_dependency_acyclic\noccurrence_causation_acyclic\nevent_causation_acyclic\noccurrence_seed_complete\nrelation_claim_admissible\nsemantic_cut_complete\npre_effect_current\noperation_grant_contains_effect\nevent_scope_compatible\nfrontier_complete\ntransition_subject_complete",
