      ],
      "key": "msg_replay_proof",
      "label": "Msg-replay proof"
    },
    {
      "conditions": ["Under SPEC_METHOD.md and TICKET_METHOD.md.", "A short iteration window has per-change proof cost above expected correction cost."],
      "definition": "UX sprint compliance escrow is a bounded cost-optimization treatment allowing local UX proof deferral without weakening the process model. Sprint-close eligibility and product UX method closure are separate predicates.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 474,
          "quote": "Under `SPEC_METHOD.md` and `TICKET_METHOD.md`, a UX sprint may defer local UX\ncompliance proof during a short iteration window when per-change proof cost is\nhigher than expected correction cost.\n\nThis is a cost-optimization rule. It does not weaken the UX process model.",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/UX_METHOD.md#UX%20Method%2F13.%20Adoption%20Guidance%2F13B.%20UX%20Sprint%20Compliance%20Escrow",
          "start_line": 470
