      ],
      "key": "ux_sprint_escrow",
      "label": "UX sprint compliance escrow"
    },
    {
      "conditions": [],
      "definition": "WORLD_MODEL_METHOD.md is the world-model constitutional method document; its introductory marker does not itself adopt or execute the method.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 3,
          "quote": "# World Model Method\n\n<!-- STDO3_PROFILE_BINDING_START -->",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/WORLD_MODEL_METHOD.md#World%20Model%20Method",
